            u_xlat2.xz = (-u_xlat0.xy) * u_xlat1.xx;
            u_xlat2.xz = (-u_xlat2.xz) * vec2(vec2(_length, _length)) + u_xlat39.xy;
            u_xlat4 = texture(inputImg, u_xlat2.xz);
            u_xlat5.z = u_xlat1.x * 3.0 + -1.5;
            u_xlat5.y = -abs(u_xlat5.z) + 1.0;
            u_xlat5.x = (-u_xlat5.z);
            u_xlat5.xyz = u_xlat5.xyz;
            u_xlat5.xyz = clamp(u_xlat5.xyz, 0.0, 1.0);
            u_xlat2.xzw = u_xlat4.xyz * u_xlat5.xyz;
            u_xlat2.xzw = u_xlat2.xzw * vec3(3.0, 3.0, 3.0) + (-u_xlat4.xyz);
            u_xlat4.xyz = vec3(vec3(_dispersion, _dispersion, _dispersion)) * u_xlat2.xzw + u_xlat4.xyz;
            u_xlat3 = u_xlat3 + u_xlat4;
        }
        u_xlat0.x = float(int(_samples));
        u_xlat6 = u_xlat3 / u_xlat0.xxxx;
    }
    u_xlat0 = u_xlat21.xxxx * u_xlat6;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
